CREATE UNIQUE INDEX hayvanlar_kupe_no_key ON public.hayvanlar USING btree (kupe_no) WHERE ((durum = 'Aktif'::text) AND (kupe_no IS NOT NULL) AND (kupe_no <> ''::text));
