CREATE TRIGGER trg_padok_transfer_gorev AFTER UPDATE ON public.hayvanlar FOR EACH ROW WHEN ((new.padok_id IS DISTINCT FROM old.padok_id)) EXECUTE FUNCTION fn_padok_transfer_gorev_kapat();
